7	/**
8	 * @fileoverview Factory for creating browser agent definitions with configured tools.
9	 *
10	 * This factory is called when the browser agent is invoked via delegate_to_agent.
11	 * It creates a BrowserManager, connects the isolated MCP client, wraps tools,
12	 * and returns a fully configured LocalAgentDefinition.
13	 *
14	 * IMPORTANT: The MCP tools are ONLY available to the browser agent's isolated
15	 * registry. They are NOT registered in the main agent's ToolRegistry.
16	 */
17	
18	import type { Config } from '../../config/config.js';
19	import { AuthType } from '../../core/contentGenerator.js';
20	import type { LocalAgentDefinition } from '../types.js';
21	import type { MessageBus } from '../../confirmation-bus/message-bus.js';
22	import type { AnyDeclarativeTool } from '../../tools/tools.js';
23	import { BrowserManager } from './browserManager.js';
24	import {
25	  BrowserAgentDefinition,
26	  type BrowserTaskResultSchema,
27	} from './browserAgentDefinition.js';
28	import { createMcpDeclarativeTools } from './mcpToolWrapper.js';
29	import { createAnalyzeScreenshotTool } from './analyzeScreenshot.js';
30	import { injectAutomationOverlay } from './automationOverlay.js';
31	import { injectInputBlocker } from './inputBlocker.js';
32	import { debugLogger } from '../../utils/debugLogger.js';
33	
34	/**
35	 * Creates a browser agent definition with MCP tools configured.
36	 *
37	 * This is called when the browser agent is invoked via delegate_to_agent.
38	 * The MCP client is created fresh and tools are wrapped for the agent's
39	 * isolated registry - NOT registered with the main agent.
40	 *
41	 * @param config Runtime configuration
42	 * @param messageBus Message bus for tool invocations
43	 * @param printOutput Optional callback for progress messages
44	 * @returns Fully configured LocalAgentDefinition with MCP tools
45	 */
46	export async function createBrowserAgentDefinition(
47	  config: Config,
48	  messageBus: MessageBus,
49	  printOutput?: (msg: string) => void,
50	): Promise<{
51	  definition: LocalAgentDefinition<typeof BrowserTaskResultSchema>;
52	  browserManager: BrowserManager;
53	}> {
54	  debugLogger.log(
55	    'Creating browser agent definition with isolated MCP tools...',
56	  );
57	
58	  // Create and initialize browser manager with isolated MCP client
59	  const browserManager = new BrowserManager(config);
60	  await browserManager.ensureConnection();
61	
62	  if (printOutput) {
63	    printOutput('Browser connected with isolated MCP client.');
64	  }
65	
66	  // Determine if input blocker should be active (non-headless + enabled)
67	  const shouldDisableInput = config.shouldDisableBrowserUserInput();
68	  // Inject automation overlay and input blocker if not in headless mode
69	  const browserConfig = config.getBrowserAgentConfig();
70	  if (!browserConfig?.customConfig?.headless) {
71	    if (printOutput) {
72	      printOutput('Injecting automation overlay...');
73	    }
74	    await injectAutomationOverlay(browserManager);
75	    if (shouldDisableInput) {
76	      if (printOutput) {
77	        printOutput('Injecting input blocker...');
78	      }
79	      await injectInputBlocker(browserManager);
80	    }
81	  }
82	
83	  // Create declarative tools from dynamically discovered MCP tools
84	  // These tools dispatch to browserManager's isolated client
85	  const mcpTools = await createMcpDeclarativeTools(
86	    browserManager,
87	    messageBus,
88	    shouldDisableInput,
89	  );
90	  const availableToolNames = mcpTools.map((t) => t.name);
91	
92	  // Validate required semantic tools are available
93	  const requiredSemanticTools = [
94	    'click',
95	    'fill',
96	    'navigate_page',
97	    'take_snapshot',
98	  ];
99	  const missingSemanticTools = requiredSemanticTools.filter(
100	    (t) => !availableToolNames.includes(t),
101	  );
102	  if (missingSemanticTools.length > 0) {
103	    debugLogger.warn(
104	      `Semantic tools missing (${missingSemanticTools.join(', ')}). ` +
105	        'Some browser interactions may not work correctly.',
106	    );
107	  }
108	
109	  // Only click_at is strictly required — text input can use press_key or fill.
110	  const requiredVisualTools = ['click_at'];
111	  const missingVisualTools = requiredVisualTools.filter(
112	    (t) => !availableToolNames.includes(t),
113	  );
114	
115	  // Check whether vision can be enabled; returns undefined if all gates pass.
116	  function getVisionDisabledReason(): string | undefined {
117	    const browserConfig = config.getBrowserAgentConfig();
118	    if (!browserConfig.customConfig.visualModel) {
119	      return 'No visualModel configured.';
120	    }
121	    if (missingVisualTools.length > 0) {
122	      return (
123	        `Visual tools missing (${missingVisualTools.join(', ')}). ` +
124	        `The installed chrome-devtools-mcp version may be too old.`
125	      );
126	    }
127	    const authType = config.getContentGeneratorConfig()?.authType;
128	    const blockedAuthTypes = new Set([
129	      AuthType.LOGIN_WITH_GOOGLE,
130	      AuthType.LEGACY_CLOUD_SHELL,
131	      AuthType.COMPUTE_ADC,
132	    ]);
133	    if (authType && blockedAuthTypes.has(authType)) {
134	      return 'Visual agent model not available for current auth type.';
135	    }
136	    return undefined;
137	  }
138	
139	  const allTools: AnyDeclarativeTool[] = [...mcpTools];
140	  const visionDisabledReason = getVisionDisabledReason();
141	
142	  if (visionDisabledReason) {
143	    debugLogger.log(`Vision disabled: ${visionDisabledReason}`);
144	  } else {
145	    allTools.push(
146	      createAnalyzeScreenshotTool(browserManager, config, messageBus),
147	    );
148	  }
149	
150	  debugLogger.log(
151	    `Created ${allTools.length} tools for browser agent: ` +
152	      allTools.map((t) => t.name).join(', '),
153	  );
154	
155	  // Create configured definition with tools
156	  // BrowserAgentDefinition is a factory function - call it with config
157	  const baseDefinition = BrowserAgentDefinition(config, !visionDisabledReason);
158	  const definition: LocalAgentDefinition<typeof BrowserTaskResultSchema> = {
159	    ...baseDefinition,
160	    toolConfig: {
161	      tools: allTools,
162	    },
163	  };
164	
165	  return { definition, browserManager };
166	}
167	
168	/**
169	 * Cleans up browser resources after agent execution.
170	 *
171	 * @param browserManager The browser manager to clean up
172	 */
173	export async function cleanupBrowserAgent(
174	  browserManager: BrowserManager,
175	): Promise<void> {
176	  try {
177	    await browserManager.close();
178	    debugLogger.log('Browser agent cleanup complete');
179	  } catch (error) {
180	    debugLogger.error(
181	      `Error during browser cleanup: ${error instanceof Error ? error.message : String(error)}`,
182	    );
183	  }
184	}
