7	/**
8	 * @fileoverview Creates DeclarativeTool classes for MCP tools.
9	 *
10	 * These tools are ONLY registered in the browser agent's isolated ToolRegistry,
11	 * NOT in the main agent's registry. They dispatch to the BrowserManager's
12	 * isolated MCP client directly.
13	 *
14	 * Tool definitions are dynamically discovered from chrome-devtools-mcp
15	 * at runtime, not hardcoded.
16	 */
17	
18	import type { FunctionDeclaration } from '@google/genai';
19	import type { Tool as McpTool } from '@modelcontextprotocol/sdk/types.js';
20	import {
21	  type ToolConfirmationOutcome,
22	  DeclarativeTool,
23	  BaseToolInvocation,
24	  Kind,
25	  type ToolResult,
26	  type ToolInvocation,
27	  type ToolCallConfirmationDetails,
28	  type PolicyUpdateOptions,
29	} from '../../tools/tools.js';
30	import type { MessageBus } from '../../confirmation-bus/message-bus.js';
31	import type { BrowserManager, McpToolCallResult } from './browserManager.js';
32	import { debugLogger } from '../../utils/debugLogger.js';
33	import { suspendInputBlocker, resumeInputBlocker } from './inputBlocker.js';
34	import { MCP_TOOL_PREFIX } from '../../tools/mcp-tool.js';
35	import { BROWSER_AGENT_NAME } from './browserAgentDefinition.js';
36	
37	/**
38	 * Tools that interact with page elements and require the input blocker
39	 * overlay to be temporarily SUSPENDED (pointer-events: none) so
40	 * chrome-devtools-mcp's interactability checks pass.  The overlay
41	 * stays in the DOM — only the CSS property toggles, zero flickering.
42	 */
43	const INTERACTIVE_TOOLS = new Set([
44	  'click',
45	  'click_at',
46	  'fill',
47	  'fill_form',
48	  'hover',
49	  'drag',
50	  'upload_file',
51	]);
52	
53	/**
54	 * Tool invocation that dispatches to BrowserManager's isolated MCP client.
55	 */
56	class McpToolInvocation extends BaseToolInvocation<
57	  Record<string, unknown>,
58	  ToolResult
59	> {
60	  constructor(
61	    protected readonly browserManager: BrowserManager,
62	    protected readonly toolName: string,
63	    params: Record<string, unknown>,
64	    messageBus: MessageBus,
65	    private readonly shouldDisableInput: boolean,
66	  ) {
67	    super(
68	      params,
69	      messageBus,
70	      `${MCP_TOOL_PREFIX}${BROWSER_AGENT_NAME}_${toolName}`,
71	      toolName,
72	      BROWSER_AGENT_NAME,
73	    );
74	  }
75	
76	  getDescription(): string {
77	    return `Calling MCP tool: ${this.toolName}`;
78	  }
79	
80	  protected override async getConfirmationDetails(
81	    _abortSignal: AbortSignal,
82	  ): Promise<ToolCallConfirmationDetails | false> {
83	    if (!this.messageBus) {
84	      return false;
85	    }
86	
87	    return {
88	      type: 'mcp',
89	      title: `Confirm MCP Tool: ${this.toolName}`,
90	      serverName: BROWSER_AGENT_NAME,
91	      toolName: this.toolName,
92	      toolDisplayName: this.toolName,
93	      onConfirm: async (outcome: ToolConfirmationOutcome) => {
94	        await this.publishPolicyUpdate(outcome);
95	      },
96	    };
97	  }
98	
99	  override getPolicyUpdateOptions(
100	    _outcome: ToolConfirmationOutcome,
101	  ): PolicyUpdateOptions | undefined {
102	    return {
103	      mcpName: BROWSER_AGENT_NAME,
104	    };
105	  }
106	
107	  /**
108	   * Whether this specific tool needs the input blocker suspended
109	   * (pointer-events toggled to 'none') before execution.
110	   */
111	  private get needsBlockerSuspend(): boolean {
112	    return this.shouldDisableInput && INTERACTIVE_TOOLS.has(this.toolName);
113	  }
114	
115	  async execute(signal: AbortSignal): Promise<ToolResult> {
116	    try {
117	      // Suspend the input blocker for interactive tools so
118	      // chrome-devtools-mcp's interactability checks pass.
119	      // Only toggles pointer-events CSS — no DOM change, no flicker.
120	      if (this.needsBlockerSuspend) {
121	        await suspendInputBlocker(this.browserManager);
122	      }
123	
124	      const result: McpToolCallResult = await this.browserManager.callTool(
125	        this.toolName,
126	        this.params,
127	        signal,
128	      );
129	
130	      // Extract text content from MCP response
131	      let textContent = '';
132	      if (result.content && Array.isArray(result.content)) {
133	        textContent = result.content
134	          .filter((c) => c.type === 'text' && c.text)
135	          .map((c) => c.text)
136	          .join('\n');
137	      }
138	
139	      // Post-process to add contextual hints for common error patterns
140	      const processedContent = postProcessToolResult(
141	        this.toolName,
142	        textContent,
143	      );
144	
145	      // Resume input blocker after interactive tool completes.
146	      if (this.needsBlockerSuspend) {
147	        await resumeInputBlocker(this.browserManager);
148	      }
149	
150	      if (result.isError) {
151	        return {
152	          llmContent: `Error: ${processedContent}`,
153	          returnDisplay: `Error: ${processedContent}`,
154	          error: { message: textContent },
155	        };
156	      }
157	
158	      return {
159	        llmContent: processedContent || 'Tool executed successfully.',
160	        returnDisplay: processedContent || 'Tool executed successfully.',
161	      };
162	    } catch (error) {
163	      const errorMsg = error instanceof Error ? error.message : String(error);
164	
165	      // Chrome connection errors are fatal — re-throw to terminate the agent
166	      // immediately instead of returning a result the LLM would retry.
167	      if (errorMsg.includes('Could not connect to Chrome')) {
168	        throw error;
169	      }
170	
171	      // Resume on error path too so the blocker is always restored
172	      if (this.needsBlockerSuspend) {
173	        await resumeInputBlocker(this.browserManager).catch(() => {});
174	      }
175	
176	      debugLogger.error(`MCP tool ${this.toolName} failed: ${errorMsg}`);
177	      return {
178	        llmContent: `Error: ${errorMsg}`,
179	        returnDisplay: `Error: ${errorMsg}`,
180	        error: { message: errorMsg },
181	      };
182	    }
183	  }
184	}
